    """Validate the fields required to handle a request."""
    if data is None:
        raise ValueError("request data is required")

    if client_id is None:
        raise ValueError("client_id is required")

    if isinstance(client_id, str) and not client_id.strip():
        raise ValueError("client_id must not be blank")


def handle_request(data, client_id):
    """Validate, rate-limit, and process an incoming API request."""
    _validate_request(data, client_id)

    if not check_rate_limit(client_id):
        raise RuntimeError("rate limit exceeded")

    return process(data)

